        "lines": [
          {
            "id": "source-25r-001",
            "speaker": "Пассажир",
            "en": "Hey, man. Airport?",
            "ru": "Привет. До аэропорта довезёте?",
            "stage": ""
          },
          {
            "id": "source-25r-002",
            "speaker": "Водитель",
            "en": "Sure, sure. Which terminal?",
            "ru": "Конечно. В какой терминал?",
            "stage": ""
          },
          {
            "id": "source-25r-003",
            "speaker": "Пассажир",
            "en": "Uh, B, I think. Roughly how much is that?",
            "ru": "Э-э, B, кажется. Сколько примерно будет стоить?",
            "stage": ""
          },
          {
            "id": "source-25r-004",
            "speaker": "Водитель",
            "en": "Forty-five, give or take. Depends on the traffic on the bridge.",
            "ru": "Около сорока пяти. Зависит от пробок на мосту.",
            "stage": ""
          },
          {
            "id": "source-25r-005",
            "speaker": "Пассажир",
            "en": "And time-wise? My flight's at nine.",
            "ru": "А по времени? У меня рейс в девять.",
            "stage": ""
          },
          {
            "id": "source-25r-006",
            "speaker": "Водитель",
            "en": "Normally, twenty-five minutes, more or less.",
            "ru": "Обычно примерно двадцать пять минут.",
            "stage": ""
          },
          {
            "id": "source-25r-007",
            "speaker": "Пассажир",
            "en": "Normally. And today?",
            "ru": "Обычно. А сегодня?",
            "stage": ""
          },
          {
            "id": "source-25r-008",
            "speaker": "Водитель",
            "en": "You want a wild guess?",
            "ru": "Навскидку прикинуть?",
            "stage": "смеётся"
          },
          {
            "id": "source-25r-009",
            "speaker": "Пассажир",
            "en": "Sure.",
            "ru": "Давайте.",
            "stage": ""
          },
          {
            "id": "source-25r-010",
            "speaker": "Водитель",
            "en": "Friday, five thirty, it's raining. Forty minutes. Maybe fifty.",
            "ru": "Пятница, полшестого, дождь. Минут сорок. Может, пятьдесят.",
            "stage": ""
          },
          {
            "id": "source-25r-011",
            "speaker": "Пассажир",
            "en": "Ugh. That figures. The one day I'm in a hurry.",
            "ru": "Эх, ну конечно. Именно сегодня, когда я спешу.",
            "stage": ""
          },
          {
            "id": "source-25r-012",
            "speaker": "Водитель",
            "en": "No worries, my friend. I know a back road. We can skip the bridge.",
            "ru": "Не переживайте. Я знаю объездную дорогу. Можно объехать мост.",
            "stage": ""
          },
          {
            "id": "source-25r-013",
            "speaker": "Пассажир",
            "en": "Seriously? You're a legend.",
            "ru": "Серьёзно? Вот спасибо!",
            "stage": ""
          },
          {
            "id": "source-25r-014",
            "speaker": "Водитель",
            "en": "Twenty years driving here. Put the bag in the back.",
            "ru": "Двадцать лет здесь вожу. Кладите сумку назад.",
            "stage": ""
          },
          {
            "id": "source-25r-015",
            "speaker": "Пассажир",
            "en": "Just a backpack. I travel light.",
            "ru": "Только рюкзак. Путешествую налегке.",
            "stage": ""
          },
          {
            "id": "source-25r-016",
            "speaker": "Водитель",
            "en": "Smart man. Let's go.",
            "ru": "И правильно. Поехали.",
            "stage": ""
          }
        ]
